def adjudicate_ucp600_presentation(
    lc_ref: str,
    lc_amount_usd: float,
    invoice_amount: float,
    lc_desc: str,
    invoice_desc: str,
    days_since_shipment: int,
    is_clean_bol: bool,
    is_charter_party: bool,
    insurance_coverage_pct: float
) -> dict:
    # UCP 600 Documentary Credit Forensic Examination Engine
    discrepancies = []
    if invoice_amount != lc_amount_usd:
        discrepancies.append(f"Invoice amount ${invoice_amount:,.2f} differs from LC ${lc_amount_usd:,.2f}")
    if invoice_desc != lc_desc:
        discrepancies.append(f"Goods description mismatch: '{invoice_desc}' vs '{lc_desc}' (Art 18)")
    if days_since_shipment > 21:
        discrepancies.append(f"Stale presentation: presented {days_since_shipment} days after shipment (Art 14c)")
    if not is_clean_bol:
        discrepancies.append("Bill of Lading is claused (Art 27)")
    if is_charter_party:
        discrepancies.append("Unauthorized charter-party Bill of Lading presented (Art 22)")
    if insurance_coverage_pct < 110.0:
        discrepancies.append(f"Insurance coverage {insurance_coverage_pct}% is below statutory 110% CIF requirement (Art 28)")

    if discrepancies:
        return {
            'lc_ref': lc_ref,
            'status': 'DISCREPANT_REFUSED_UCP600_ART16',
            'swift_message': 'MT-734 Notice of Refusal',
            'discrepancies_count': len(discrepancies),
            'discrepancies': discrepancies,
            'disposition': 'Documents held at the disposal of the presenting bank'
        }
    else:
        return {
            'lc_ref': lc_ref,
            'status': 'COMPLYING_PRESENTATION_HONORED',
            'swift_message': 'MT-756 Advice of Reimbursement',
            'discrepancies_count': 0,
            'disposition': 'Honor payment to beneficiary'
        }

lc_res = adjudicate_ucp600_presentation('LC-BMB-2026-9901', 15000000.0, 15000000.0, 'Grade A LNG', 'Grade A LNG', 24, True, True, 105.0)
print("=== ICC UCP 600 Documentary Credit Adjudication Scorecard ===")
print(f"Letter of Credit Ref:     {lc_res['lc_ref']} | Status: {lc_res['status']}")
print(f"Discrepancies Identified: {lc_res['discrepancies_count']} defects detected")
for d in lc_res['discrepancies']:
    print(f"  - Violation: {d}")
print(f"SWIFT Operational Action: {lc_res['swift_message']} ({lc_res['disposition']})")

def reconcile_nostro_camt053_statement(
    initial_nostro_balance_usd: float = 30000000.0,
    mirror_ledger: list = None,
    camt053_entries: list = None
) -> dict:
    # Automated Nostro Mirror vs ISO 20022 Statement Reconciler
    if mirror_ledger is None:
        mirror_ledger = [
            {'ref': 'SWIFT-OUT-001', 'amount_usd': -5000000.0},
            {'ref': 'SWIFT-OUT-002', 'amount_usd': -10000000.0}
        ]
    if camt053_entries is None:
        camt053_entries = [
            {'ref': 'SWIFT-OUT-001', 'amount_usd': -5000000.0},
            {'ref': 'UNANNOUNCED-DEBIT', 'amount_usd': -45000000.0}
        ]

    matched_refs = []
    closing_balance_usd = initial_nostro_balance_usd

    for stmt_item in camt053_entries:
        closing_balance_usd += stmt_item['amount_usd']
        for mirr_item in mirror_ledger:
            if stmt_item['ref'] == mirr_item['ref'] and abs(stmt_item['amount_usd'] - mirr_item['amount_usd']) < 0.01:
                matched_refs.append(stmt_item['ref'])
                break

    overdraft_active = closing_balance_usd < 0.0
    remedy = 'EXECUTE_SPOT_USD_PURCHASE' if overdraft_active else 'NONE'
    funding_required_usd = abs(closing_balance_usd) + 5000000.0 if overdraft_active else 0.0

    return {
        'initial_balance_usd': initial_nostro_balance_usd,
        'closing_balance_usd': closing_balance_usd,
        'matched_count': len(matched_refs),
        'overdraft_active': overdraft_active,
        'remedy_action': remedy,
        'emergency_funding_usd': funding_required_usd
    }

rec_res = reconcile_nostro_camt053_statement()
print("=== Nostro Mirror Book & ISO 20022 camt.053 Reconciliation Docket ===")
print(f"Initial Nostro Balance:   ${rec_res['initial_balance_usd']:,.2f} USD")
print(f"Closing Statement Balance:${rec_res['closing_balance_usd']:,.2f} USD (Overdraft Active: {rec_res['overdraft_active']})")
print(f"Matched Items Reconciled: {rec_res['matched_count']} entries affirmed")
print(f"Emergency Action Mandate: {rec_res['remedy_action']} (Amount: ${rec_res['emergency_funding_usd']:,.2f} USD)")
